{  
  "distractors": [  
    {  
      "text": "They prioritize economic growth above all else, as shown by their support for the bridge proposal.",  
      "why_wrong": "This contradicts the text, which shows that many islanders oppose the bridge due to fears of overdevelopment and loss of cultural identity. The debate highlights a strong concern for preservation, not economic growth as the top priority."  
    },  
    {  
      "text": "They believe that environmental concerns are irrelevant compared to the benefits of improved transportation.",  
      "why_wrong": "The text explicitly states that environmental preservation is a central reason for opposing the bridge, with local historian Eleanor Finch warning about harming the island’s ecosystem. This distractor ignores key evidence from the passage."  
    },  
    {  
      "text": "They are united in their desire to eliminate the ferry service in favor of a faster, more modern connection to the mainland.",  
      "why_wrong": "The text presents a clear divide: some support the bridge, while others strongly advocate for upgrading the ferry. The idea of universal support for replacing the ferry is directly contradicted by the ongoing debate."  
    },  
    {  
      "text": "They view the current ferry service as outdated and ineffective, making a bridge the only viable solution.",  
      "why_wrong": "The text does not claim the ferry is ineffective—on the contrary, ferry advocates argue it’s reliable and cost-effective. The debate centers on choice, not on the ferry being obsolete."  
    },  
    {  
      "text": "They are indifferent to the island’s cultural heritage and focus solely on practical transportation needs.",  
      "why_wrong": "The passage emphasizes that cultural preservation and identity are central to the opposition to the bridge. The islanders’ attachment to tradition and natural beauty is repeatedly highlighted."  
    },  
    {  
      "text": "They believe that increased tourism will inevitably lead to lower living standards and should be discouraged.",  
      "why_wrong": "While tourism is a concern, the text does not suggest islanders want to discourage it entirely. Instead, they fear *uncontrolled* tourism due to overdevelopment—this distractor misrepresents their nuanced position."  
    }  
  ]  
}
